<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Billiards Game</title>
    <style>
        body {
            background-color: #222;
            color: #eee;
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }
        #game-container {
            position: relative;
            box-shadow: 0 0 50px rgba(0,0,0,0.5);
            border: 10px solid #333;
        }
        canvas {
            display: block;
            background-color: #076324;
        }
        #ui {
            margin-top: 20px;
            text-align: center;
        }
        button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            background-color: #444;
            color: white;
            border: none;
            border-radius: 4px;
            transition: background 0.2s;
        }
        button:hover {
            background-color: #666;
        }
        .instructions {
            margin-top: 10px;
            color: #aaa;
            font-size: 0.9em;
        }
    </style>
</head>
<body>

    <div id="game-container">
        <canvas id="gameCanvas"></canvas>
    </div>

    <div id="ui">
        <button id="resetBtn">Reset / Rack</button>
        <div class="instructions">
            Click the white ball, drag backward to aim, and release to shoot.
        </div>
    </div>

<script>
(function() {
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const resetBtn = document.getElementById('resetBtn');

    // Simulation configuration
    const W = 700;
    const H = 350;
    const R = 10;
    const OFFSET_X = 50;
    const OFFSET_Y = 50;

    canvas.width = W + (OFFSET_X * 2);
    canvas.height = H + (OFFSET_Y * 2);

    class PhysicsSim {
        constructor(W, H, R) {
            this.W = W;
            this.H = H;
            this.R = R;
            this.balls = [];
            this.paused = false;
            this.friction = 0.15; // damping factor
        }

        reset(newBalls) {
            this.balls = newBalls.map(b => ({
                x: b.x,
                y: b.y,
                vx: b.vx || 0,
                vy: b.vy || 0,
                cue: !!b.cue,
                potted: false
            }));
        }

        state() {
            return this.balls.map(b => ({
                x: b.x,
                y: b.y,
                vx: b.vx,
                vy: b.vy,
                potted: b.potted,
                cue: b.cue
            }));
        }

        shoot(vx, vy) {
            const cueBall = this.balls.find(b => b.cue && !b.potted);
            if (cueBall) {
                cueBall.vx = vx;
                cueBall.vy = vy;
            }
        }

        pause() { this.paused = true; }
        resume() { this.paused = false; }

        step(dt) {
            this._physics_step(dt);
            this.draw();
        }

        _physics_step(dt) {
            const friction_decay = Math.exp(-this.friction * dt);

            // 1. Motion & Friction
            for (let b of this.balls) {
                if (b.potted) {
                    b.vx = 0; b.vy = 0;
                    continue;
                }
                b.x += b.vx * dt;
                b.y += b.vy * dt;
                b.vx *= friction_decay;
                b.vy *= friction_decay;

                if (Math.abs(b.vx) < 0.1) b.vx = 0;
                if (Math.abs(b.vy) < 0.1) b.vy = 0;
            }

            // 2. Cushions
            for (let b of this.balls) {
                if (b.potted) continue;
                if (b.x < this.R) { b.x = this.R; b.vx *= -1; }
                else if (b.x > this.W - this.R) { b.x = this.W - this.R; b.vx *= -1; }

                if (b.y < this.R) { b.y = this.R; b.vy *= -1; }
                else if (b.y > this.H - this.R) { b.y = this.H - this.R; b.vy *= -1; }
            }

            // 3. Ball-to-ball collisions (Elastic)
            for (let i = 0; i < this.balls.length; i++) {
                for (let j = i + 1; j < this.balls.length; j++) {
                    const b1 = this.balls[i];
                    const b2 = this.balls[j];
                    if (b1.potted || b2.potted) continue;

                    const dx = b2.x - b1.x;
                    const dy = b2.y - b1.y;
                    const distSq = dx * dx + dy * dy;
                    const minDist = this.R * 2;

                    if (distSq < minDist * minDist) {
                        const dist = Math.sqrt(distSq);
                        const nx = dx / dist;
                        const ny = dy / dist;

                        // Resolve overlap (Static collision resolution)
                        const overlap = minDist - dist;
                        b1.x -= nx * (overlap / 2);
                        b1.y -= ny * (overlap / 2);
                        b2.x += nx * (overlap / 2);
                        b2.y += ny * (overlap / 2);

                        // Impulse resolution
                        const rvx = b2.vx - b1.vx;
                        const rvy = b2.vy - b1.vy;
                        const velAlongNormal = rvx * nx + rvy * ny;

                        if (velAlongNormal < 0) {
                            // Elastic collision impulse (e=1, m1=m2)
                            const j_impulse = -2 * velAlongNormal / 2;
                            b1.vx -= j_impulse * nx;
                            b1.vy -= j_impulse * ny;
                            b2.vx += j_impulse * nx;
                            b2.vy += j_impulse * ny;
                        }
                    }
                }
            }

            // 4. Pockets
            const pockets = [
                {x: 0, y: 0}, {x: W/2, y: 0}, {x: W, y: 0},
                {x: 0, y: H}, {x: W/2, y: H}, {x: W, y: H}
            ];
            const pocketRadius = this.R * 1.5;
            const pocketR2 = pocketRadius * pocketRadius;

            for (let b of this.balls) {
                if (b.potted) continue;
                for (let p of pockets) {
                    const dx = b.x - p.x;
                    const dy = b.y - p.y;
                    if (dx*dx + dy*dy < pocketR2) {
                        b.potted = true;
                        b.vx = 0;
                        b.vy = 0;
                        break;
                    }
                }
            }
        }

        draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw Table shadow/border
            ctx.fillStyle = '#332211';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Playfield
            ctx.fillStyle = '#076324';
            ctx.fillRect(OFFSET_X, OFFSET_Y, W, H);

            // Draw Rails
            ctx.strokeStyle = '#5d3a1a';
            ctx.lineWidth = 15;
            ctx.strokeRect(OFFSET_X, OFFSET_Y, W, H);

            // Draw Pockets
            ctx.fillStyle = '#111';
            const pSize = this.R * 1.5;
            const pCoords = [
                [0,0], [W/2, 0], [W, 0],
                [0, H], [W/2, H], [W, H]
            ];
            pCoords.forEach(c => {
                ctx.beginPath();
                ctx.arc(c[0], c[1], pSize, 0, Math.PI * 2);
                ctx.fill();
            });

            // Draw Balls
            this.balls.forEach(b => {
                if (b.potted) return;
                const bx = b.x + OFFSET_X;
                const by = b.y + OFFSET_Y;

                // Ball body
                ctx.beginPath();
                ctx.arc(bx, by, this.R, 0, Math.PI * 2);
                ctx.fillStyle = b.cue ? '#fff' : '#e74c3c';
                if (b.cue) {
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5;
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                } else {
                    ctx.shadowBlur = 0;
                }
                ctx.fill();
                ctx.shadowBlur = 0;

                // Ball Highlight
                ctx.beginPath();
                ctx.arc(bx - this.R/3, by - this.R/3, this.R/4, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(255,255,255,0.3)';
                ctx.fill();

                // Ball Outline
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            });
        }
    }

    function getRack() {
        const balls = [];
        // Cue ball
        balls.push({ x: 150, y: 200, vx: 0, vy: 0, cue: true });

        // 15 balls in a triangle
        const startX = 480;
        const startY = 200;
        const spacingX = 21;
        const spacingY = 19;

        for (let row = 0; row < 5; row++) {
            for (let col = 0; col <= row; col++) {
                balls.push({
                    x: startX + row * spacingX,
                    y: startY + (col - row / 2) * spacingY,
                    vx: 0,
                    vy: 0,
                    cue: false
                });
            }
        }
        return balls;
    }

    const sim = new PhysicsSim(W, H, R);
    window.sim = sim;

    // Mouse Interaction
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let dragEnd = { x: 0, y: 0 };

    canvas.addEventListener('mousedown', (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left - OFFSET_X;
        const my = e.clientY - rect.top - OFFSET_Y;

        const cueBall = sim.balls.find(b => b.cue && !b.potted);
        if (cueBall) {
            const dx = mx - cueBall.x;
            const dy = my - cueBall.y;
            if (Math.sqrt(dx*dx + dy*dy) < R * 3) {
                isDragging = true;
                dragStart = { x: cueBall.x, y: cueBall.y };
                dragEnd = { x: mx, y: my };
            }
        }
    });

    window.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const rect = canvas.getBoundingClientRect();
        dragEnd.x = e.clientX - rect.left - OFFSET_X;
        dragEnd.y = e.clientY - rect.top - OFFSET_Y;
        sim.draw();
    });

    window.addEventListener('mouseup', (e) => {
        if (!isDragging) return;
        isDragging = false;

        const cueBall = sim.balls.find(b => b.cue && !b.potted);
        if (cueBall) {
            // Direction is from mouse position BACK to cue ball position
            // If I drag from (100,100) to (50,50), the vector is (50,50)
            // which is (Start - End)
            const vx = (dragStart.x - dragEnd.x) * 15;
            const vy = (dragStart.y - dragEnd.y) * 15;
            sim.shoot(vx, vy);
        }
        sim.draw();
    });

    // Animation Loop
    function loop() {
        if (!sim.paused) {
            sim.step(1/60);
        } else {
            sim.draw();
        }

        // Draw aim line overlay
        if (isDragging) {
            const cueBall = sim.balls.find(b => b.cue && !b.potted);
            if (cueBall) {
                const bx = cueBall.x + OFFSET_X;
                const by = cueBall.y + OFFSET_Y;

                // The vector for the shot is the inverse of the drag vector
                const dx = (dragStart.x - dragEnd.x);
                const dy = (dragStart.y - dragEnd.y);

                // Draw the drag line (white dashed)
                ctx.beginPath();
                ctx.setLineDash([5, 5]);
                ctx.moveTo(bx, by);
                ctx.lineTo(bx + dx, by + dy); // Simplified visual
                // Actually, visual cue: draw a line from ball to mouse position
                ctx.setLineDash([5, 5]);
                ctx.moveTo(bx, by);
                ctx.lineTo(dragEnd.x + OFFSET_X, dragEnd.y + OFFSET_Y);
                ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
                ctx.stroke();
                ctx.setLineDash([]);

                // Draw the predicted shot line (solid yellow)
                ctx.beginPath();
                ctx.moveTo(bx, by);
                ctx.lineTo(bx + dx * 5, by + dy * 5);
                ctx.strokeStyle = "yellow";
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.lineWidth = 1;
            }
        }

        requestAnimationFrame(loop);
    }

    resetBtn.addEventListener('click', () => {
        sim.reset(getRack());
        sim.draw();
    });

    // Initialization
    sim.reset(getRack());
    requestAnimationFrame(loop);

})();
</script>
</body>
</html>

